// ===== Ported from Kianna's version: Training Guides data =====
const bohTrainingGuidesData = [{"id": "primary", "icon": "🥪", "color": "#C41E3A", "title": "Primary Training Guide", "titleEs": "Guía de Formación Primaria", "sections": [{"title": "1. Assemble with Accuracy", "items": ["Prioritize mobile orders or requests from FOH.", "Apply the correct label to all special sandwiches.", "Place filet cup-side down with 2 pickles — 3 for small filets.", "Fold foil bags ½ inch, ensuring no oil stains.", "Drop sandwiches into the correct chute — Drive-Thru or Front Counter — within 45 seconds.", "Build all special sandwiches accurately with correct toppings such as cheese, lettuce, and tomato."]}, {"title": "2. Stock & Support the Line", "items": ["Use Lean Entree iPad & KPS when stocking chutes to reduce overstocking and understocking.", "Multigrain buns should always be hot and available — keep at least 3 ready.", "Prep pickle buns ahead of time — 9 with pickles, 3 without during peak hours.", "Pre-assemble four deluxe setups during peak times – avoid over prepping.", "Keep cheese and produce fully stocked at the centerline."]}, {"title": "3. Check Quality & Temp Everything", "items": ["All products must temp at 140°F or higher — pay close attention to grilled items.", "Filets should have grill marks facing up and evenly spaced.", "Visually inspect every product for quality: proper size, consistent coater coverage and color, and no bald spots.", "Always reset timers when adding new product.", "Place all discarded products into cooldown and track in VSBL once expired.", "Discard buns, cheese, produce, or protein immediately if expired."]}, {"title": "4. Flow & Rotate", "items": ["Primary 1 is the point person that calls all chicken to the machines person.", "Always be proactive when calling for chicken.", "Primary 1 is the point person that communicates all holds to the Bagging Captain.", "Follow AHA hold times & ensure FIFO is being used for ALL Products.", "Primary 1, 2, and 3 should work as a team - support each position as needed.", "Step in to assist with fry drops as needed.", "Stay alert to catering orders - Promise Times & Destinations to properly prepare.", "DO NOT bump the order without a plan in place."]}, {"title": "5. Protect the Zone", "items": ["Change gloves between tasks.", "Sanitize all surfaces regularly.", "Keep all pans covered when not in use.", "Eliminate standing water, cross-contact risks, clutter, and paper towels.", "Operate in full alignment with the Food Safety 5 at all times."]}], "sectionsEs": [{"title": "1. Ensamblar con precisión", "items": ["Priorizar pedidos móviles o solicitudes desde FOH.", "Aplicar la etiqueta correcta a todos los sándwiches especiales.", "Coloque el filete con el lado de la taza hacia abajo con 2 pepinillos (3 para filetes pequeños).", "Dobla las bolsas de aluminio ½ pulgada, asegurándote de que no queden manchas de aceite.", "Coloque los sándwiches en el distribuidor correcto (Drive-Thru o Front Counter) en 45 segundos.", "Prepare todos los sándwiches especiales con precisión y con los ingredientes correctos, como queso, lechuga y tomate."]}, {"title": "2. Abastecer y apoyar la línea", "items": ["Utilice Lean Entree iPad y KPS al abastecer los canales para reducir el exceso y la falta de existencias.", "Los panecillos multigrano siempre deben estar calientes y disponibles: tenga al menos 3 listos.", "Prepare los panecillos con pepinillos con anticipación: 9 con pepinillos y 3 sin ellos durante las horas pico.", "Prepare con antelación cuatro configuraciones de lujo durante las horas pico: evite preparar demasiado.", "Mantenga el queso y los productos frescos completamente abastecidos en la línea central."]}, {"title": "3. Verifique la calidad y la temperatura de todos los productos", "items": ["Todos los productos deben tener una temperatura de 140°F o más; preste mucha atención a los alimentos asados.", "Los filetes deben tener las marcas de la parrilla hacia arriba y espaciadas uniformemente.", "Inspeccione visualmente cada producto para verificar su calidad: tamaño adecuado, cobertura y color uniformes y ausencia de zonas sin pintura.", "Restablezca siempre los temporizadores al agregar un nuevo producto.", "Coloque todos los productos descartados en tiempo de recuperación y realice un seguimiento en VSBL una vez que caduquen.", "Deseche los panecillos, el queso, los productos agrícolas o las proteínas inmediatamente si están vencidos."]}, {"title": "4. Fluir y rotar", "items": ["Primario 1 es la persona clave que llama a todos los pollos a la persona de las máquinas.", "Sea siempre proactivo al llamar para pedir pollo.", "Primario 1 es la persona clave que comunica todas las retenciones al Capitán de Embolsado.", "Siga los tiempos de espera de AHA y asegúrese de que se utilice FIFO para TODOS los productos.", "Los primarios 1, 2 y 3 deben trabajar en equipo: apoyar cada puesto según sea necesario.", "Intervenga para ayudar con el descenso de las frituras según sea necesario.", "Manténgase alerta a los pedidos de catering - Promise Times & Destinations para prepararse adecuadamente.", "NO cancele el pedido sin un plan establecido."]}, {"title": "5. Proteger la zona", "items": ["Cambie los guantes entre tareas.", "Desinfecte todas las superficies periódicamente.", "Mantenga todas las cacerolas cubiertas cuando no estén en uso.", "Elimine el agua estancada, los riesgos de contacto cruzado, el desorden y las toallas de papel.", "Operar en total alineación con el Principio de Seguridad Alimentaria 5 en todo momento."]}]}, {"id": "secondary", "icon": "🥗", "color": "#0099CC", "title": "Secondary Training Guide", "titleEs": "Guía de Formación Secundaria", "sections": [{"title": "1. Assemble with Accuracy", "items": ["Prioritize mobile orders or requests from FOH.", "Complete all special items with the correct portion, label, and protein - strive to complete in 45 seconds.", "Add proteins to salads only when they temp at 140°F or higher.", "Portion mac and soup correctly — serve hot and fresh.", "Use the correct utensils and gloves for each product type.", "Complete salads and slide under the chute within 1 minute."]}, {"title": "2. Stock & Support the Line", "items": ["Use Lean Entree iPad & KPS when stocking chutes to reduce overstocking and understocking.", "Press the correct label for nuggets or strips to ensure proper ventilation.", "Place packaging in the chute free of excess oil or mess.", "Slide Kanban trays across the counter upon request and communicate with Prep.", "Have sufficient cookies, mac, and bacon baked — use ovens efficiently to maintain product availability without waste.", "Have brownies and soup ready to serve — check sufficient product is thawed and available."]}, {"title": "3. Check Quality & Temp Everything", "items": ["All products must temp at 140°F or higher — pay close attention to grilled items.", "Visually inspect every product for quality: proper size, consistent coater coverage and color, and no bald spots.", "Always reset timers when adding new product.", "Place all discarded products into cooldown and track in VSBL once expired."]}, {"title": "4. Flow & Rotate", "items": ["Secondary 1 is the point person that calls all chicken to the machines person — always be proactive when calling for chicken.", "Secondary 1 is the point person that communicates all holds to the Bagging Captain.", "Communicate special salad or prep needs to the Prep team in real time.", "Follow AHA hold times & ensure FIFO is being used for ALL Products.", "Secondary 1, 2, and 3 should work as a team - support each position as needed.", "Step in to assist with fry drops as needed.", "Stay alert to catering orders - Promise Times & Destinations to properly prepare.", "DO NOT bump the order without a plan in place."]}, {"title": "5. Protect the Zone", "items": ["Change gloves between tasks.", "Sanitize all surfaces regularly.", "Keep all pans covered when not in use.", "Eliminate standing water, cross-contact risks, clutter, and paper towels.", "Operate in full alignment with the Food Safety 5 at all times."]}], "sectionsEs": [{"title": "1. Ensamblar con precisión", "items": ["Priorizar pedidos móviles o solicitudes desde FOH.", "Complete todos los elementos especiales con la porción, etiqueta y proteína correctas: intente completarlos en 45 segundos.", "Agregue proteínas a las ensaladas solo cuando la temperatura sea de 140°F o más.", "Distribuya correctamente los macarrones con queso y la sopa: sírvalos calientes y frescos.", "Utilice los utensilios y guantes adecuados para cada tipo de producto.", "Ensaladas completas y deslícelas bajo el conducto en 1 minuto."]}, {"title": "2. Abastecer y apoyar la línea", "items": ["Utilice Lean Entree iPad y KPS al abastecer los canales para reducir el exceso y la falta de existencias.", "Presione la etiqueta correcta para nuggets o tiras para garantizar una ventilación adecuada.", "Coloque el embalaje en el conducto libre de exceso de aceite o suciedad.", "Bandejas Kanban laterales al otro lado del mostrador a pedido y comunicación con Preparación.", "Tenga suficientes galletas, macarrones y tocino horneados — utilice los hornos de manera eficiente para mantener la disponibilidad del producto sin desperdicio.", "Tenga brownies y sopa listos para servir — compruebe que haya suficiente producto descongelado y disponible."]}, {"title": "3. Verifique la calidad y la temperatura de todo", "items": ["Todos los productos deben tener una temperatura de 140°F o más; preste mucha atención a los alimentos asados.", "Inspeccione visualmente cada producto para verificar su calidad: tamaño adecuado, cobertura y color uniformes y ausencia de zonas sin pintura.", "Restablezca siempre los temporizadores al agregar un nuevo producto.", "Coloque todos los productos descartados en tiempo de recuperación y realice un seguimiento en VSBL una vez que caduquen."]}, {"title": "4. Fluir y rotar", "items": ["El secundario 1 es la persona clave que llama a todos los pollos a la persona de las máquinas — sea siempre proactivo al llamar para pedir pollo.", "El Secundario 1 es la persona clave que comunica todas las retenciones al Capitán de Ensacado.", "Comunique necesidades especiales de ensalada o preparación al equipo de preparación en tiempo real.", "Siga los tiempos de espera de AHA y asegúrese de que se utilice FIFO para TODOS los productos.", "Los secundarios 1, 2 y 3 deben trabajar en equipo: apoyar cada posición según sea necesario.", "Intervenir para ayudar con las caídas de frituras según sea necesario.", "Manténgase alerta a los pedidos de catering - Promise Times & Destinations para prepararse adecuadamente.", "NO cancele el pedido sin un plan establecido."]}, {"title": "5. Proteger la zona", "items": ["Cambie los guantes entre tareas.", "Desinfecte todas las superficies periódicamente.", "Mantenga todas las cacerolas cubiertas cuando no estén en uso.", "Elimine el agua estancada, los riesgos de contacto cruzado, el desorden y las toallas de papel.", "Operar en total alineación con el Principio de Seguridad Alimentaria 5 en todo momento."]}]}, {"id": "fries", "icon": "🍟", "color": "#F5A623", "title": "Fries Training Guide", "titleEs": "Guía de Entrenamiento de Papas Fritas", "sections": [{"title": "1. Drop with Timing", "items": ["Drop fries proactively based on guest flow and real-time need — never too early, never too late.", "Respond immediately to “boost drop” calls from Baggers — drop 2 baskets if needed.", "Maintain a steady pace during peak hours; drop smaller batches during slower periods."]}, {"title": "2. Fry & Finish Right", "items": ["Apply correct date labels and “Use First” stickers.", "Fill Kanbans intentionally and accurately — never overproduce.", "Rotate product using First In, First Out (FIFO) — place the newest items in the back and oldest items in the front.", "Position prepped product to support upcoming dayparts."]}, {"title": "3. Stage for Quality & Speed", "items": ["Keep all containers covered when not in use — including prep table lids, protein pans, and wrap trays.", "Wraps must be tightly sealed and stored securely.", "Store utensils properly — never leave them in sinks or open spaces.", "Wipe and sanitize work surfaces between every task."]}, {"title": "4. Watch & Rotate", "items": ["Pause Kanban prep to support made-to-order items when waves hit.", "Ask: “Where can I add the most value right now?”", "Support cold line teammates, restock, or assist with guest-facing needs.", "Always prioritize the current guest — Stop, Drop, & Serve."]}, {"title": "5. Protect the Zone", "items": ["Wipe spills promptly to prevent slips and oil buildup.", "Always store the scoop in its designated holder — never on top of fries.", "Prevent all cross-contamination.", "Operate in full alignment with the Food Safety 5 at all times."]}], "sectionsEs": [{"title": "1. Caída con sincronización", "items": ["Entregue papas fritas de manera proactiva en función del flujo de huéspedes y las necesidades en tiempo real: nunca es demasiado temprano, nunca es demasiado tarde.", "Responda de inmediato a los llamados de “boost drop” de los Baggers: deje caer 2 canastas si es necesario.", "Mantenga un ritmo constante durante las horas pico y realice lotes más pequeños durante los períodos más lentos."]}, {"title": "2. Freír y terminar correctamente", "items": ["Coloque las etiquetas de fecha correctas y las pegatinas de “Usar primero”.", "Llene los Kanbans de manera intencional y precisa; nunca produzca en exceso.", "Rotar productos usando el principio Primero en entrar, primero en salir (FIFO): colocar los artículos más nuevos atrás y los más antiguos adelante.", "Coloque el producto preparado para apoyar las próximas franjas horarias."]}, {"title": "3. Etapa de Calidad y Velocidad", "items": ["Mantenga todos los recipientes cubiertos cuando no estén en uso, incluidas las tapas de las mesas de preparación, las bandejas de proteínas y las bandejas para envolver alimentos.", "Los envoltorios deben estar bien sellados y almacenados de forma segura.", "Guarde los utensilios de forma adecuada: nunca los deje en fregaderos o espacios abiertos.", "Limpie y desinfecte las superficies de trabajo entre cada tarea."]}, {"title": "4. Mirar y girar", "items": ["Pausa la preparación de Kanban para dar soporte a los artículos hechos a pedido cuando llegan las olas.", "Pregúntate: “¿Dónde puedo aportar el mayor valor ahora mismo?”", "Brindar apoyo a los compañeros de la línea fría, reabastecer o ayudar con las necesidades de atención al cliente.", "Priorice siempre al huésped actual: Detener, Dejar y Servir."]}, {"title": "5. Proteger la zona", "items": ["Limpie los derrames rápidamente para evitar resbalones y acumulación de aceite.", "Guarde siempre la cuchara en el soporte correspondiente, nunca sobre las patatas fritas.", "Prevenir toda contaminación cruzada.", "Operar en total alineación con el Principio de Seguridad Alimentaria 5 en todo momento."]}]}, {"id": "machines", "icon": "⚙️", "color": "#546E7A", "title": "Machines Training Guide", "titleEs": "Guía de Entrenamiento de Máquinas", "sections": [{"title": "1. Drop with Discipline", "items": ["Stir nuggets in an “X” pattern before securing the lid.", "Drop all chicken using the tiered method — lower, raise 4 inches, then lower again.", "Ensure lids are fully secured, and timers are started immediately.", "Allow chicken to drain for a full 10 seconds before transferring to pans.", "Change gloves and aprons when they become dirty or contaminated."]}, {"title": "2. Set & Secure", "items": ["Set an individual timer for each batch of chicken.", "Complete filter lockouts proactively and accurately.", "Keep fryers clean, organized, and free of excess crumbs throughout the shift."]}, {"title": "3. Watch & Rotate", "items": ["Monitor the AHA system consistently — rotate pans before the 20-minute expiration.", "Aim for 90% or higher compliance in under-20-minute rotations.", "Work with Boards to scan expired product and move to cool-down as needed."]}, {"title": "4. Call the Drops", "items": ["Sift the coater frequently for even coverage.", "Wipe the breading table constantly — no build-up or crust.", "Keep milk wash clean and free of debris — replace when cloudy.", "Prevent standing water and eliminate cross-contact between raw and ready areas."]}, {"title": "5. Protect the Zone", "items": ["Never cross-contaminate raw and ready-to-eat products.", "Sanitize all tools and equipment frequently — no buildup or debris.", "Maintain a clean environment — no standing water, dirty trays, or oil spills.", "Check oil levels and cleanliness consistently throughout the shift.", "Operate with 100% alignment to the Food Safety 5 standards."]}], "sectionsEs": [{"title": "1. Soltar con disciplina", "items": ["Revuelva las pepitas en forma de “X” antes de asegurar la tapa.", "Deje caer todo el pollo usando el método escalonado: bájelo, súbalo 4 pulgadas y luego bájelo nuevamente.", "Asegúrese de que las tapas estén completamente aseguradas y que los temporizadores se inicien de inmediato.", "Deje que el pollo se escurra durante 10 segundos completos antes de transferirlo a las bandejas.", "Cambie los guantes y delantales cuando se ensucien o contaminen."]}, {"title": "2. Configurar y asegurar", "items": ["Establezca un temporizador individual para cada lote de pollo.", "Bloqueos completos de filtros de forma proactiva y precisa.", "Mantenga las freidoras limpias, organizadas y libres de migas sobrantes durante todo el turno."]}, {"title": "3. Mirar y girar", "items": ["Supervise el sistema AHA de forma constante: gire las bandejas antes de que transcurran 20 minutos.", "Intente lograr un cumplimiento del 90% o más en rotaciones de menos de 20 minutos.", "Trabaje con las juntas para escanear productos vencidos y moverlos al enfriamiento según sea necesario."]}, {"title": "4. Llama a las gotas", "items": ["Tamice el aplicador con frecuencia para lograr una cobertura uniforme.", "Limpie la mesa de empanizado constantemente: no se acumularán restos ni se formarán costras.", "Mantenga el lavado de leche limpio y libre de residuos; reemplácelo cuando esté turbio.", "Evite el agua estancada y elimine el contacto cruzado entre las áreas crudas y preparadas."]}, {"title": "5. Proteger la zona", "items": ["Nunca contamine de forma cruzada productos crudos y listos para consumir.", "Desinfecte todas las herramientas y equipos con frecuencia, sin acumulaciones ni residuos.", "Mantenga un ambiente limpio: sin agua estancada, bandejas sucias o derrames de aceite.", "Verifique los niveles de aceite y la limpieza constantemente durante todo el turno.", "Operar con 100% de alineación a los estándares de Seguridad Alimentaria 5."]}]}, {"id": "prep", "icon": "🥬", "color": "#2E7D32", "title": "Prep Training Guide", "titleEs": "Guía de Entrenamiento de Preparación", "sections": [{"title": "1. Assemble with Accuracy", "items": ["Ensure all items meet Chick-fil-A recipes and specs — use sidekicks and specials screen to assemble all regular and special items accurately.", "Follow proper portion control procedures: weigh all appropriate ingredients using the digital scale 100% of the time; use correct utensils for each item to prevent cross-contamination; use fill lines and visual guides.", "Strive to assemble accurate specials in 45 seconds."]}, {"title": "2. Stock & Support the Line", "items": ["Apply correct date labels to all prep items.", "Fill Kanbans intentionally and accurately based on “build to” guidelines — never overproduce unless instructed for a catering/large order.", "Ensure sufficient ingredients are on-hand and available to be prepped: shredded and sliced chicken, chopped lettuce & tomatoes, produce items and fruit; check sufficient product is thawed — corn, corn & black beans, etc.", "Notify a leader immediately if at risk of running out of product."]}, {"title": "3. Check Quality & Temp Everything", "items": ["Ensure all prep items are temping at 40 degrees or below.", "Keep all containers covered when not in use — including prep table lids, protein pans, and wrap trays; wraps must be tightly sealed and stored securely.", "Inspect quality of product and remove any that does not meet QIV standards — set product aside and let a leader know to request credit for the items."]}, {"title": "4. Flow & Rotate", "items": ["Pause Kanban prep to support made-to-order items when waves hit.", "Support Boards teammates, restock, or assist with guest-facing needs. Ask: “Where can I add the most value right now?”", "Always prioritize the current guest — Stop, Drop, & Serve.", "Rotate product using First In, First Out (FIFO) — place the newest items in the back and oldest items in the front."]}, {"title": "5. Protect the Zone", "items": ["Surfaces must be wiped and sanitized regularly.", "Keep all pans covered when not in use.", "Store utensils properly — never leave them in sinks or open spaces.", "Eliminate standing water, clutter, paper towels, and cross-contact risks.", "Operate in full alignment with the Food Safety 5 at all times."]}], "sectionsEs": [{"title": "1. Ensamblar con precisión", "items": ["Asegúrese de que todos los artículos cumplan con las recetas y especificaciones de Chick-fil-A — use los compañeros y la pantalla de especiales para ensamblar todos los elementos regulares y especiales con precisión.", "Siga los procedimientos adecuados de control de porciones: pese todos los ingredientes apropiados utilizando la balanza digital el 100% del tiempo; utilice los utensilios adecuados para cada artículo para evitar la contaminación cruzada; utilice líneas de relleno y guías visuales.", "Esfuércese por crear especialidades precisas en 45 segundos."]}, {"title": "2. Abastecer y apoyar la línea", "items": ["Aplique etiquetas de fecha correctas a todos los elementos de preparación.", "Llene los Kanbans intencionalmente y con precisión según las pautas de “construcción a medida”; nunca produzca en exceso a menos que se le indique para un servicio de catering o un pedido grande.", "Asegúrese de que haya suficientes ingredientes a mano y disponibles para preparar: pollo desmenuzado y en rodajas, lechuga picada y tomates, productos y frutas; compruebe que se haya descongelado suficiente producto — maíz, maíz y frijoles negros, etc.", "Notificar a un líder inmediatamente si corremos el riesgo de quedarnos sin producto."]}, {"title": "3. Verifique la calidad y la temperatura de todo", "items": ["Asegúrese de que todos los elementos de preparación tengan una temperatura de 40 grados o menos.", "Mantenga todos los recipientes cubiertos cuando no estén en uso, incluidas las tapas de las mesas de preparación, las bandejas de proteínas y las bandejas para envolver alimentos; los envoltorios deben estar bien sellados y almacenados de forma segura.", "Inspeccionar la calidad del producto y eliminar cualquiera que no cumpla con los estándares QIV — coloque el producto a un lado y avísele a un líder para solicitar crédito por los artículos."]}, {"title": "4. Fluir y rotar", "items": ["Pausa la preparación de Kanban para dar soporte a los artículos hechos a pedido cuando llegan las olas.", "Apoyar a los compañeros de equipo de Boards, reabastecer o ayudar con las necesidades de atención al cliente. Pregúntate: “¿Dónde puedo aportar el mayor valor ahora mismo?”", "Priorice siempre al huésped actual: Detener, Dejar y Servir.", "Rotar productos usando el principio Primero en entrar, primero en salir (FIFO): colocar los artículos más nuevos atrás y los más antiguos adelante."]}, {"title": "5. Proteger la zona", "items": ["Las superficies deben limpiarse y desinfectarse periódicamente.", "Mantenga todas las cacerolas cubiertas cuando no estén en uso.", "Guarde los utensilios de forma adecuada: nunca los deje en fregaderos o espacios abiertos.", "Elimine el agua estancada, el desorden, las toallas de papel y los riesgos de contacto cruzado.", "Operar en total alineación con el Principio de Seguridad Alimentaria 5 en todo momento."]}]}, {"id": "breading", "icon": "🍗", "color": "#C41E3A", "title": "Breading Training Guide", "titleEs": "Guía de Entrenamiento para Empanado", "sections": [{"title": "1. Drop with Purpose", "items": ["Follow Lean iPad instructions unless directed otherwise by the Chicken Champion (machines).", "Drop based on Kanban visual cues — holding pans and business volume.", "Never drop based on habit or guesswork.", "Communicate with the team when adjustments are needed."]}, {"title": "2. Bread with Precision", "items": ["Filets — Grip by the tips, fully submerge in milk wash, drip for 3–5 seconds, and press with even body weight.", "Nuggets — Separate fully in milk wash, drip for 10 seconds, and avoid clumps.", "Strips — Bread like nuggets, place with tips inward and “on their backs.”", "Coating must be even — no bald spots or thick clumps."]}, {"title": "3. Load with Discipline", "items": ["No overlapping in fry baskets or on the grill.", "Tips must face inward toward the centerline.", "Grilled filets and nuggets should be spaced out with no contact.", "Use sanitized tools and clean trays to transfer product."]}, {"title": "4. Clean as You Go", "items": ["Sift the coater frequently for even coverage.", "Wipe the breading table constantly — no build-up or crust.", "Keep milk wash clean and free of debris — replace when cloudy.", "Prevent standing water and eliminate cross-contact between raw and ready areas."]}, {"title": "5. Protect the Zone", "items": ["Keep the floors clean.", "Sanitize all surfaces regularly.", "Set timers properly and remove product at the correct time.", "Only yellow gloves and aprons are allowed in the breading zone.", "Never leave the breading zone wearing a yellow apron or gloves.", "Operate in full alignment with the Food Safety 5 at all times."]}], "sectionsEs": [{"title": "1. Soltar con propósito", "items": ["Siga las instrucciones de Lean iPad a menos que el Chicken Champion le indique lo contrario.", "Caída basada en señales visuales de Kanban: retención de bandejas y volumen de negocios.", "Nunca abandones por hábito o conjeturas.", "Comunicarse con el equipo cuando se necesiten ajustes."]}, {"title": "2. Pan con precisión", "items": ["Filetes: Sujételos por las puntas, sumérjalos completamente en la mezcla de leche, déjelos gotear durante 3 a 5 segundos y presione con el peso del cuerpo de manera uniforme.", "Nuggets: sepárelos completamente con agua con leche, déjelos escurrir durante 10 segundos y evite que se formen grumos.", "Tiras: Nuggets similares a pan, colocados con las puntas hacia adentro y “boca arriba.”", "El recubrimiento debe ser uniforme, sin zonas calvas ni grumos gruesos."]}, {"title": "3. Carga con disciplina", "items": ["No superponer en cestas para freír ni en la parrilla.", "Las puntas deben mirar hacia adentro, hacia la línea central.", "Los filetes y nuggets a la parrilla deben estar espaciados y sin contacto.", "Utilice herramientas desinfectadas y bandejas limpias para transferir el producto."]}, {"title": "4. Limpia sobre la marcha", "items": ["Tamice el aplicador con frecuencia para lograr una cobertura uniforme.", "Limpie la mesa de empanizado constantemente: no se acumularán restos ni se formarán costras.", "Mantenga el lavado de leche limpio y libre de residuos; reemplácelo cuando esté turbio.", "Evite el agua estancada y elimine el contacto cruzado entre las áreas crudas y preparadas."]}, {"title": "5. Proteger la zona", "items": ["Mantenga los pisos limpios.", "Desinfecte todas las superficies periódicamente.", "Configure los temporizadores correctamente y retire el producto en el momento correcto.", "En la zona de empanado sólo se permiten guantes y delantales amarillos.", "Nunca abandone la zona de empanado vistiendo un delantal o guantes amarillos.", "Operar en total alineación con el Principio de Seguridad Alimentaria 5 en todo momento."]}]}, {"id": "trainer", "icon": "🎓", "color": "#6A4C93", "title": "Trainer Training Guide", "titleEs": "Guía de Formación de Entrenadores", "sections": [{"title": "1. Engage with Energy", "items": ["Greet the team warmly - use names and create personal connections.", "Share goals and expectations and why it matters.", "Bring positivity and high energy - stay encouraging under pressure.", "Use CORE 4 and positive tones to make coaching exciting.", "Set the rhythm of the zone by moving with hustle, even in between waves."]}, {"title": "2. Model Excellence", "items": ["Demonstrate PEC behaviors.", "Role Model WHED by executing on OE and delivering on 2nd Mile.", "Maintain appearance standards (make it look attractive).", "Hustle with purpose and joy, never rushed, always intentional.", "Always align on Wave Theory."]}, {"title": "3. Train with Clarity", "items": ["Break tasks into clear, simple steps.", "Always utilize DIR training method: Demonstrate, Imitate, Repeat.", "Avoid too much information, focus on what matters most first.", "Check for understanding often: “Could you explain this back to me?”", "Coach in the moment, don’t let wrong standards go unnoticed."]}, {"title": "4. Celebrate and Challenge", "items": ["Celebrate effort, not just perfection.", "Utilize Oreo Method for feedback: start with a positive, give clear and kind correction, end with encouragement or recognition.", "Coach opportunities immediately and kindly.", "Keep feedback specific, kind and actionable.", "Gamify zone and create “small wins” to create growth.", "Balance fun with standards — don’t just celebrate by lowering the bar of excellence."]}, {"title": "5. Grow the Future", "items": ["Always explain the “why” behind what we do.", "Challenge team to take ownership, encourage team members to coach peers when they demonstrate mastery.", "Stay invested in team’s growth, reinforce that the meaning of the role is more than just tasks — it’s development of people.", "Use your own story as inspiration for the future."]}], "sectionsEs": [{"title": "1. Interactuar con la energía", "items": ["Salude cálidamente al equipo: use nombres y cree conexiones personales.", "Compartir objetivos y expectativas y por qué es importante.", "Aporta positividad y mucha energía: mantente alentador bajo presión.", "Utilice CORE 4 y tonos positivos para hacer que el coaching sea emocionante.", "Marca el ritmo de la zona moviéndote con agilidad, incluso entre olas."]}, {"title": "2. Excelencia del modelo", "items": ["Demostrar comportamientos PEC.", "Ser un modelo a seguir de WHED ejecutando el OE y cumpliendo en la segunda milla.", "Mantener los estándares de apariencia (hacer que se vea atractivo).", "Ajetreo con propósito y alegría, nunca apresurado, siempre intencional.", "Alinearse siempre con la teoría de ondas."]}, {"title": "3. Entrena con claridad", "items": ["Divida las tareas en pasos claros y sencillos.", "Utilice siempre el método de entrenamiento DIR: Demostrar, Imitar, Repetir.", "Evite demasiada información, concéntrese primero en lo que más importa.", "Comprueba con frecuencia la comprensión: “¿Podrías explicarme esto?”", "Entrena en el momento, no dejes que los estándares erróneos pasen desapercibidos."]}, {"title": "4. Celebrar y desafiar", "items": ["Celebre el esfuerzo, no sólo la perfección.", "Utilice el método Oreo para obtener retroalimentación: comienza con algo positivo, da una corrección clara y amable, termina con un estímulo o reconocimiento.", "Oportunidades de coaching de inmediato y amablemente.", "Mantenga los comentarios específicos, amables y procesables.", "Gamificar la zona y crear “pequeñas victorias” para generar crecimiento.", "Equilibre la diversión con los estándares, no se limite a celebrar bajando el listón de la excelencia."]}, {"title": "5. Cultivar el futuro", "items": ["Explicar siempre el “por qué” detrás de lo que hacemos.", "Desafiar al equipo a asumir la responsabilidad, alentar a los miembros del equipo a capacitar a sus compañeros cuando demuestren dominio.", "Mantenerse involucrado en el crecimiento de los equipos, reforzar el significado del rol es más que solo tareas, es el desarrollo de las personas.", "Utilice su propia historia como inspiración para el futuro."]}]}];
const fohTrainingGuidesData = [{"id": "host", "icon": "🙋", "color": "#C41E3A", "title": "Host Training Guide", "sections": [{"title": "1. Smile & Shine", "items": ["Make every guest feel seen — greet immediately with a warm smile and genuine eye contact.", "Wave and share a personal welcome, like “We’re so glad you’re here at Chick-fil-A Buda!”", "Open doors for arriving guests with enthusiasm and intention — this is their first impression, make it count."]}, {"title": "2. Greet & Seat", "items": ["Personally escort dine-in guests to their table — offer menus and begin the order with a smile.", "Anticipate family needs — offer high chairs or coloring kits before they ask.", "Clearly walk guests through the tableside ordering process — reassure them, answer questions, and set the tone for a relaxed experience.", "For carry-out guests, meet them where they are at Host stand or Front Counter and walk them to the pickup bench. Don’t point — guide with hospitality in motion."]}, {"title": "3. Lead, Offer, Repeat", "items": ["Ask for guest names and use them throughout the experience — connection begins with a name.", "Confirm spelling, destination, and table number — accuracy is part of honor.", "Take the lead in ordering — generously suggest 1–2 items, confirm sauces, and repeat the full order with care.", "Anticipate what they might forget — napkins, bendy straws, extra sauce — and offer it before they ask."]}, {"title": "4. Create a Welcoming Environment (PPG: Personalized, Proactive, Generous)", "items": ["Touch every table with purpose — smile, ask by name, and check in with care: “May I refresh your Sweet Tea?” “May I grab you another Chick-fil-A Sauce?” “Would a wet wipe or mint make your meal feel complete?”", "Always be scanning — clear trays, wipe spills, and refill as you go.", "Maintain a space that feels cared for — sparkling tables, spotless floors, clean windows, and full condiment stands.", "Speak with elevated hospitality and always lead with Core 4: eye contact, a smile, speak enthusiastically, and stay connected.", "Delight kids and families with personalized touches — offer balloons, cow hats, coloring kits, or stickers with joy.", "Clear tables before guests get up — create space for connection and turn the table for the next guest without ever making them feel rushed."]}, {"title": "5. Protect the Zone", "items": ["Watch for guests preparing to leave — open the door for them and offer a heartfelt thank you.", "Say goodbye like a friend would: “We loved having you today — can’t wait to see you again!”", "If a guest had a special moment, mention it again — “So glad we could celebrate that birthday with you!”"]}]}, {"id": "ipos", "icon": "📱", "color": "#0099CC", "title": "iPOS Training Guide", "sections": [{"title": "1. Smile & Shine", "items": ["Wave confidently at or above eye level to warmly welcome each guest — set the tone with energy and presence.", "Make your greeting personal: “Hi there! We’re so glad you’re here — how’s your day going so far?”", "Use your posture, eye contact, and smile to communicate that they matter."]}, {"title": "2. Catch Every Detail", "items": ["Ask for the guest’s name with sincerity — use it throughout the interaction to build connection and care.", "Accurately input vehicle make, model, color, lane, and first 3 license plate letters.", "Confirm spelling if unsure, and repeat the name back with a smile.", "For vehicles without a front plate, quickly check for the registration sticker to keep things moving.", "Use the tag feature for hearing-impaired guests and ensure all communication is clear and respectful."]}, {"title": "3. Lead, Offer, Repeat", "items": ["Take the lead in the ordering process — be confident, kind, and clear: “I’d be happy to get that started for you. Would you like to make it a large today?” “Would you like to add a cookie or frozen treat to finish off your meal?”", "Confirm sauces, drinks, and special requests so the guest feels fully taken care of.", "Always offer 1–3 thoughtful upsell suggestions with generosity — not pressure.", "Speak with warmth and professionalism: follow Core 4 and elevated hospitality language standards.", "Use the HEARD model with grace if you need to recover a moment — make it feel effortless and caring."]}, {"title": "4. Close Gaps & Call It Out", "items": ["Keep the line moving by being aware of your zone: during peak times, begin taking orders at the crosswalk; during slower times, serve with excellence at the menu board.", "Proactively direct guests beyond the canopy to ensure a smooth flow — smile, wave, and guide them like a host.", "When a large or complex order comes through, call it in early via walkie: 30-count nuggets, 4 or more of the same item, 8 or more strips, 10-count minis.", "Use clear callouts to your team — “Tendered!” lets the next order taker know to slide up and serve without delay.", "Speak to both guests and teammates like they’re family — with clarity and care."]}, {"title": "5. Friendly Farewell", "items": ["End every interaction with a tone of joy and gratitude: “Thank you so much for choosing us today — we’ll see you soon!” “It was a pleasure serving you, and we hope the rest of your day is just as great!”", "Let the guest leave feeling seen, appreciated, and excited to come back."]}]}, {"id": "runner", "icon": "🏃", "color": "#FF6F61", "title": "Runner Training Guide", "sections": [{"title": "1. Smile & Shine", "items": ["Make every guest feel seen — greet immediately with a warm smile and genuine eye contact.", "Wave and share a personal welcome, like “We’re so glad you’re here at Chick-fil-A Buda!”", "Open doors for arriving guests with enthusiasm and intention — this is their first impression, make it count.", "Speak with warmth and professionalism: follow Core 4 and elevated hospitality language standards."]}, {"title": "2. Grab & Go", "items": ["Serve in priority order: Carry-Out/Mobile → Dine-In → 3rd-Party. Don’t overlook small orders like drinks or desserts — every guest matters.", "Read the service ticket with intention: visually double-check every item — you’re the final quality check; ensure sauces, napkins, utensils are present before walking away; confirm beverage orders are accurate and complete & then paired with food.", "Deliver food immediately when it’s ready — your pace shows you care."]}, {"title": "3. Match & Hand-Off", "items": ["Deliver Dine-In meals quickly, with a personal touch and repeat part of their order with confidence: “Hi Rory! I have your spicy sandwich meal and frosted lemonade.”", "Invite the guest to verify their full order — including sauces, napkins, drinks, and extras.", "For 3rd-party orders, kindly verify and have the driver press “Confirm” before they leave.", "Own the moment — this is more than a handoff, it’s a moment to connect - PPG.", "If you see a guest waiting too long, approach with urgency and empathy — their time is valuable."]}, {"title": "4. Add Value Always", "items": ["Ask yourself: “Where can I add the most value right now?”", "If caught up, be the first to step in — check on waiting guests or lend a hand: Boost Host (table touch-ins & clean tables); Boost Bagging (prioritize smaller orders - get in & out); Boost Drinks (refill ice, teas, lemonades, cups).", "Be fully present — no standing idle. Every moment is a chance to serve."]}, {"title": "5. Friendly Farewell", "items": ["End every interaction with a tone of joy and gratitude: “Is there anything else I can do to serve you today?” “It was a pleasure serving you, and we hope the rest of your day is just as great!”", "Ensure every guest gets at least one sincere “My Pleasure” during your interaction.", "Follow with a fond farewell: “Thanks so much for coming—hope to see you again soon!”"]}]}, {"id": "omd", "icon": "🚗", "color": "#8E63FF", "title": "OMD Training Guide", "sections": [{"title": "1. Smile & Shine", "items": ["Welcome every guest by name with a wave and a warm, confident smile.", "Stay guest-facing and attentive at all times, creating connection with eye contact and cheerful energy.", "While waiting for food to land, engage guests with intentional conversation or meaningful service — offer napkins, condiments, or simply ask how their day is going."]}, {"title": "2. Grab & Go", "items": ["Prioritize speed and accuracy — grab fully paired orders (food & drinks) and deliver with precision and joy.", "Lead with urgency, but never rush — give full attention to the lead car when multiple orders are ready."]}, {"title": "3. Match & Hand-Off", "items": ["Review service ticket and confidently identify car details (make, model, color, plate, guest name).", "Confirm the guest’s name and repeat part of their order with confidence: “Hi Rory! I have your spicy sandwich meal and frosted lemonade.”", "Invite the guest to verify their full order — including sauces, napkins, drinks, and extras.", "Stay present and wait for them to finish checking before closing the interaction."]}, {"title": "4. Close Gaps & Call It Out", "items": ["Direct guests clearly to the correct zone (window, red sign, yellow sign) based on real-time traffic.", "If there’s a hold, proactively reassure the guest with warmth: “Your order is being made fresh right now—it’ll be just a moment!”", "Communicate with Baggers and Drinks as soon as you notice a missing item — don’t wait to be told.", "Stay alert for guests who seem stuck or lost — ask if they’ve scanned or if you can assist.", "When a guest is ready to exit, guide them through the middle escape lane with a smile to honor their time."]}, {"title": "5. Friendly Farewell", "items": ["End every interaction with a tone of joy and gratitude: “Is there anything else I can do to serve you today?”", "Follow with a fond farewell: “Thanks so much for coming—hope to see you again soon!”", "Invite feedback: “We’d love to hear how we did—feel free to take the survey on your receipt!”"]}]}, {"id": "drinks13", "icon": "🥤", "color": "#1B9AAA", "title": "Drinks 1/3 Training Guide", "sections": [{"title": "1. Scoop & Serve", "items": ["Stay alert to the KPS screen and move with urgency.", "Work ahead by preparing multiple drink orders at once — efficiency = excellence.", "Use the scoop for all ice: ½ cup for Sunjoy, Soft Drinks, and Lemonade; full cup for Teas (unless requested otherwise). Always use the portion button on the autofill — no guessing, just precision.", "Prioritize mobile orders for faster guest experiences — meet them where they are."]}, {"title": "2. Clean & Crisp", "items": ["Serve drinks that look as good as they taste.", "Wipe down drips, dry lids, and make sure every cup is clean to the touch.", "Think of each cup as a small detail that builds trust with the guest."]}, {"title": "3. Lid & Label", "items": ["Use the correct punch lid for every drink — accuracy is a sign of respect.", "Place the service sticker neatly on top — this is how we communicate with clarity."]}, {"title": "4. Slide & Organize", "items": ["Group 3 or more drinks in a carrier for easy handoff.", "Stage only complete drink sets — never pass along an incomplete order.", "Maintain pairing integrity — keep drinks grouped correctly, even during a rush."]}, {"title": "5. Communicate & Team Up", "items": ["If you’re over the Rule of 4, ask for a BOOST from Drinks 2 — don’t wait to fall behind.", "Call out when drinks are ready for a dessert-paired order — set the next station up for success.", "Proactively communicate restock needs — own your space and reset between waves.", "Let the OMD know when a beverage-only order is ready so they can deliver it fast."]}]}, {"id": "drinks2", "icon": "🍧", "color": "#1B9AAA", "title": "Drinks 2 Training Guide", "sections": [{"title": "1. Supply & Boost", "items": ["Start every shift with a mindset of abundance.", "Refill all teas, lemonades, and ice bins for both Drive-Thru and Front Counter.", "Maintain a full stock of cups, lids, carriers, and straws.", "Restock key ingredients: shake base, whipped cream, toppings, and dessert cups."]}, {"title": "2. Prep & Pour", "items": ["Set up Drinks 1 and 3 for success with pre-scooped ice cups when volume is high.", "Stay ahead by pre-making: 8 Medium & 6 Large lemonades (¾ full, no ice); 8 Medium & 6 Large waters (with ice)."]}, {"title": "3. Dessert & Deliver", "items": ["Craft all desserts for Drive-Thru and Front Counter with precision and care.", "Before making cones, confirm with baggers to avoid waste — listen for “Cone on Order.”"]}, {"title": "4. Clean & Clear", "items": ["Create a clean, clear, and safe space for your team.", "Use squeegees and fans to dry floors quickly and prevent slips.", "Wipe counters and machines frequently to maintain that “best-in-class” standard.", "Reset the cockpit zone between WAVES — your effort behind the scenes makes excellence visible to guests."]}, {"title": "5. Prioritize & Respond", "items": ["Always ask, “Where am I most needed right now?” and GO.", "Stay one step ahead of restocks, backups, and spills — don’t let Drinks 1/3 fall behind.", "Watch for Hurricane drinks or Rule of 4 — jump in early to help."]}]}, {"id": "bagging", "icon": "🛍️", "color": "#F5A623", "title": "Bagging Training Guide", "sections": [{"title": "1. Bump and Bag", "items": ["One Guest at a Time — Focus fully on each order to ensure 100% accuracy.", "Right Bag, Right Size — Use: 8lb bag for 1 meal; 25lb for 2 meals; multiple bags for 3+ meals (use a shopping bag if needed).", "Label with Pride — Place the receipt label neatly on the logo side, upper left corner — make it look sharp.", "Stack with Care — Proteins on the bottom, fries on top, everything upright. Tuck napkins in neatly.", "Hot & Cold Stay Gold — Separate hot and cold items to protect temperature and quality.", "Protect Quality — If it’s expired or looks off, pull it and call it back. Our guests deserve our best.", "Go for 100% — Bag every listed item: sauces, utensils, condiments. No detail too small — this completes the experience.", "When in Doubt, Check It Out — Use the Bagging Matrix and Sidekick for item verification. Standards aren’t suggestions."]}, {"title": "2. Pull & Organize", "items": ["Pull Specials — Remove special items from the chute and organize neatly by row on the counter. Clarity creates speed."]}, {"title": "3. Flow & Go", "items": ["Keep Moving — If you can’t bag an order due to a missing item, bag everything else (sauces, utensils, etc.) and return to finish.", "Step Back if Still — If you’re not moving, make room for someone who is. Flow over friction.", "Support Both Zones — Jump between DT and FC as volume shifts. Be everywhere you’re needed."]}, {"title": "4. Print & Stage", "items": ["Only bump full orders — Bumping too soon slows down the team. Complete before you commit.", "Stage with Intention — Place bagged orders and pair drinks neatly in the Runner zone.", "Call It Out — Say “Good Order!” clearly so OMD knows it’s ready to run."]}, {"title": "5. Friendly Farewell", "items": ["Communicate clearly and early with Baggers, OMD, and BOH.", "Call out: holds, delays, restock needs, and XXL orders (30ct or 4+ items)."]}]}, {"id": "trainer", "icon": "🎓", "color": "#6A4C93", "title": "Trainer Training Guide", "sections": [{"title": "1. Engage with Energy", "items": ["Greet the team warmly - use names and create personal connections.", "Share goals and expectations and why it matters.", "Bring positivity and high energy - stay encouraging under pressure.", "Use CORE 4 and positive tones to make coaching exciting.", "Set the rhythm of the zone by moving with hustle, even in between waves."]}, {"title": "2. Model Excellence", "items": ["Demonstrate PEC behaviors.", "Role Model WHED by executing on OE and delivering on 2nd Mile.", "Maintain appearance standards (make it look attractive).", "Hustle with purpose and joy, never rushed, always intentional.", "Always align on Wave Theory."]}, {"title": "3. Train with Clarity", "items": ["Break tasks into clear, simple steps.", "Always utilize DIR training method: Demonstrate, Imitate, Repeat.", "Avoid too much information, focus on what matters most first.", "Check for understanding often: “Could you explain this back to me?”", "Coach in the moment, don’t let wrong standards go unnoticed."]}, {"title": "4. Celebrate and Challenge", "items": ["Celebrate effort, not just perfection.", "Utilize Oreo Method for feedback: start with a positive, give clear and kind correction, end with encouragement or recognition.", "Coach opportunities immediately and kindly.", "Keep feedback specific, kind and actionable.", "Gamify zone and create “small wins” to create growth.", "Balance fun with standards — don’t just celebrate by lowering the bar of excellence."]}, {"title": "5. Grow the Future", "items": ["Always explain the “why” behind what we do.", "Challenge team to take ownership, encourage team members to coach peers when they demonstrate mastery.", "Stay invested in team’s growth, reinforce that the meaning of the role is more than just tasks — it’s development of people.", "Use your own story as inspiration for the future."]}]}];

function renderTrainingGuides(containerId, guides, bilingual){
  const container = document.getElementById(containerId);
  if(!container) return;
  container.innerHTML = guides.map((g, idx) => {
    const cardId = containerId + '-' + idx;
    return `
    <div class="tguide-card" style="--tg-color:${g.color};">
      <div class="tguide-header" onclick="toggleTrainingGuide('${cardId}')">
        <div class="tguide-title"><span class="tguide-icon">${g.icon}</span>${g.title}</div>
        <div class="tguide-toggle" id="tgt-${cardId}">▼</div>
      </div>
      <div class="tguide-content" id="tgc-${cardId}">
        ${bilingual ? `
        <div class="tguide-lang-row">
          <button type="button" class="tguide-lang-btn active" data-lang="en" onclick="setTrainingGuideLang('${cardId}','en')">English</button>
          <button type="button" class="tguide-lang-btn" data-lang="es" onclick="setTrainingGuideLang('${cardId}','es')">Español</button>
        </div>
        ` : ''}
        <div class="tguide-lang-panel" data-lang="en" id="tgl-en-${cardId}">
          ${g.sections.map(s => `
            <div class="pillar-section">
              <div class="pillar-label">${s.title}</div>
              <ul class="tguide-list">${s.items.map(i=>`<li>${i}</li>`).join('')}</ul>
            </div>
          `).join('')}
        </div>
        ${bilingual ? `
        <div class="tguide-lang-panel" data-lang="es" id="tgl-es-${cardId}" style="display:none;">
          ${g.sectionsEs.map(s => `
            <div class="pillar-section">
              <div class="pillar-label">${s.title}</div>
              <ul class="tguide-list">${s.items.map(i=>`<li>${i}</li>`).join('')}</ul>
            </div>
          `).join('')}
        </div>
        ` : ''}
      </div>
    </div>
    `;
  }).join('');
}

function toggleTrainingGuide(cardId){
  const content = document.getElementById('tgc-' + cardId);
  const toggle = document.getElementById('tgt-' + cardId);
  const isOpen = content.classList.contains('open');
  if(isOpen){
    content.classList.remove('open');
    toggle.classList.remove('open');
  } else {
    content.classList.add('open');
    toggle.classList.add('open');
  }
}

function setTrainingGuideLang(cardId, lang){
  const card = document.getElementById('tgc-' + cardId);
  card.querySelectorAll('.tguide-lang-btn').forEach(b=>{
    b.classList.toggle('active', b.dataset.lang === lang);
  });
  card.querySelectorAll('.tguide-lang-panel').forEach(p=>{
    p.style.display = (p.dataset.lang === lang) ? 'block' : 'none';
  });
}

